from src.tad_simple_list import TADSimpleList
from src.utils import get_input, get_service_type
from src.attendance_system import AttendanceSystem
from src.tad_double_linked_list import TADDoublyLinkedList


class SystemTerminalUI(AttendanceSystem):
    def __init__(self, tad_obj: TADDoublyLinkedList | TADSimpleList):
        super().__init__(tad_obj)
        
    def issue_ticket_ui(self):

        name = get_input(str, "  * Name: ")
        phone = get_input(int, "  * Phone: ")
        bi = get_input(str, "  * BI: ")

        attendance_type = get_service_type()
        person = self.issue_ticket(name, phone, bi, attendance_type)

        if person:
            print(f"\n  Ticket issued: {person.ticket}")

    def call_next_ui(self):
        person = self.call_next()
        if person:
            print("\n  Now serving:")
            print(f"    * Ticket: {person.ticket}")
            print(f"    * Name: {person.name}")

            wait_time = person.service_time - person.arrival_time #calcula o tempo de espera de acordo com o que está no attendance_system
            total_seconds = int(wait_time.total_seconds()) #converte o tempo para segundos
            hours = total_seconds // 3600
            minutes = total_seconds % 3600 // 60
            seconds = total_seconds % 60 #converte os segundos para formato HH:MM:SS
            print(f"    * Waiting time: {hours:02d}:{minutes:02d}:{seconds:02d}") #formata o tempo em HH:MM:SS com dois dígitos
        else:
            print("  No one waiting.")

    def show_queue_ui(self):
        queues = self.get_queues()
        
        print("\n -- Priority Queue --")
        print("   Ticket    |   Name ")
        print("-----------------------")
        if queues["priority"]:
            for person in queues["priority"]:
                print(f"    {person[0]}     |  {person[1]}")
        else:
            print("   No waiting tickets")


        print("\n\n\n -- Normal Queue --")
        print("   Ticket    |   Name ")
        print("-----------------------")
        if queues["normal"]:
            for person in queues["normal"]:
                print(f"    {person[0]}     |  {person[1]}")
        else:
            print("   No waiting tickets")

    def search_ticket_ui(self):
        ticket = input("  * Ticket number: ")

        result = self.search_ticket(ticket)

        if result:
            queue_type, person = result
            print(f"\n  Found in {queue_type} queue")
            print(f"    * Ticket: {person.ticket}")
            print(f"    * Name: {person.name}")
        else:
            print("\n   Ticket not found.")

    def remove_ticket_ui(self):
        ticket = input("  * Ticket to remove: ")

        removed = self.remove_ticket(ticket)

        if removed:
            print("\n  Ticket removed.")
        else:
            print("\n  Ticket not found.")

    def statistics_ui(self):
        stats = self.statistics()

        print("\n--- Statistics ---")
        print("  * Total served:", stats["total_served"])
        print("  * Normal waiting:", stats["normal_waiting"])
        print("  * Priority waiting:", stats["priority_waiting"])
        